-- ============================================================
-- sql/final/02_view.sql — View (butuh 03_function.sql lebih dulu)
-- Diekspor dari database db_sji (MySQL 8) setelah Finalisasi Tahap 1–10. DEFINER dihapus agar bisa diimpor
-- di komputer lain. Urutan impor: lihat sql/README.md.
-- ============================================================

DROP VIEW IF EXISTS `v_absensi_harian`;
CREATE SQL SECURITY DEFINER VIEW `v_absensi_harian` AS select `a`.`id` AS `id_absensi`,`a`.`id_karyawan` AS `id_karyawan`,`k`.`nip` AS `nip`,`k`.`nama` AS `nama`,`jl`.`nama_layanan` AS `nama_layanan`,`a`.`tgl` AS `tgl`,month(`a`.`tgl`) AS `bulan`,year(`a`.`tgl`) AS `tahun`,`a`.`jam_masuk` AS `jam_masuk`,`a`.`jam_keluar` AS `jam_keluar`,`a`.`status_kehadiran` AS `status_kehadiran`,`a`.`menit_terlambat` AS `menit_terlambat`,`fn_hitung_jam_kerja`(`a`.`jam_masuk`,`a`.`jam_keluar`) AS `jam_kerja`,`a`.`jam_lembur` AS `jam_lembur`,`a`.`id_penempatan` AS `id_penempatan`,`kl`.`nama_perusahaan` AS `nama_klien`,`p`.`lokasi_kerja` AS `lokasi_kerja`,`fn_jadwal_absensi`(`a`.`id_penempatan`,`a`.`tgl`,'datang') AS `jadwal_datang`,`fn_jadwal_absensi`(`a`.`id_penempatan`,`a`.`tgl`,'pulang') AS `jadwal_pulang`,`a`.`foto_masuk` AS `foto_masuk`,`a`.`foto_keluar` AS `foto_keluar`,((`a`.`jam_masuk` is not null) and (`a`.`jam_keluar` is null) and (timestamp(`a`.`tgl`,`a`.`jam_masuk`) < (now() - interval 16 hour))) AS `lupa_check_out`,`a`.`keterangan` AS `keterangan`,`fn_sumber_jadwal_absensi`(`a`.`id_penempatan`,`a`.`tgl`) AS `sumber_jadwal` from ((((`tbl_absensi` `a` join `tbl_karyawan` `k` on((`k`.`id` = `a`.`id_karyawan`))) left join `tbl_jenis_layanan` `jl` on((`jl`.`id` = `k`.`id_jenis_layanan`))) left join `tbl_penempatan` `p` on((`p`.`id` = `a`.`id_penempatan`))) left join `tbl_klien` `kl` on((`kl`.`id` = `p`.`id_klien`)));

DROP VIEW IF EXISTS `v_arus_kas_bulanan`;
CREATE SQL SECURITY DEFINER VIEW `v_arus_kas_bulanan` AS select year(`kas`.`tgl`) AS `tahun`,month(`kas`.`tgl`) AS `bulan`,sum(`kas`.`masuk`) AS `total_masuk`,sum(`kas`.`keluar`) AS `total_keluar`,sum((`kas`.`masuk` - `kas`.`keluar`)) AS `selisih` from (select `i`.`tgl_pembayaran` AS `tgl`,`i`.`total_tagihan` AS `masuk`,0 AS `keluar` from `tbl_invoice` `i` where ((`i`.`status` = 'Lunas') and (`i`.`tgl_pembayaran` is not null)) union all select `p`.`tgl_bayar` AS `tgl_bayar`,0 AS `0`,`p`.`total_gaji` AS `total_gaji` from `tbl_payroll` `p` where ((`p`.`status_bayar` = 'Sudah Lunas') and (`p`.`tgl_bayar` is not null)) union all select `m`.`tgl_mutasi` AS `tgl_mutasi`,(case when (`m`.`jenis` = 'Pemasukan') then `m`.`nominal` else 0 end) AS `CASE WHEN m.jenis = 'Pemasukan' THEN m.nominal ELSE 0 END`,(case when (`m`.`jenis` = 'Pengeluaran') then `m`.`nominal` else 0 end) AS `CASE WHEN m.jenis = 'Pengeluaran' THEN m.nominal ELSE 0 END` from `tbl_mutasi_keuangan` `m`) `kas` group by year(`kas`.`tgl`),month(`kas`.`tgl`);

DROP VIEW IF EXISTS `v_dashboard_eksekutif`;
CREATE SQL SECURITY DEFINER VIEW `v_dashboard_eksekutif` AS select (select count(0) from `tbl_karyawan` where ((`tbl_karyawan`.`kategori` = 'Lapangan') and (`tbl_karyawan`.`status` = 'Ditempatkan'))) AS `lapangan_bertugas`,(select count(0) from `tbl_karyawan` where ((`tbl_karyawan`.`kategori` = 'Lapangan') and (`tbl_karyawan`.`status` = 'Tersedia'))) AS `lapangan_siap`,(select count(0) from `tbl_karyawan` where ((`tbl_karyawan`.`kategori` = 'Internal') and (`tbl_karyawan`.`status` = 'Aktif'))) AS `internal_aktif`,`fn_total_piutang`() AS `total_piutang`,(((select coalesce(sum(`tbl_invoice`.`total_tagihan`),0) from `tbl_invoice` where ((`tbl_invoice`.`status` = 'Lunas') and (`tbl_invoice`.`tgl_pembayaran` between date_format(curdate(),'%Y-%m-01') and last_day(curdate())))) - (select coalesce(sum(`tbl_payroll`.`total_gaji`),0) from `tbl_payroll` where ((`tbl_payroll`.`status_bayar` = 'Sudah Lunas') and (`tbl_payroll`.`tgl_bayar` between date_format(curdate(),'%Y-%m-01') and last_day(curdate()))))) + (select coalesce(sum((case when (`tbl_mutasi_keuangan`.`jenis` = 'Pemasukan') then `tbl_mutasi_keuangan`.`nominal` else -(`tbl_mutasi_keuangan`.`nominal`) end)),0) from `tbl_mutasi_keuangan` where (`tbl_mutasi_keuangan`.`tgl_mutasi` between date_format(curdate(),'%Y-%m-01') and last_day(curdate())))) AS `profit_bulan_berjalan`;

DROP VIEW IF EXISTS `v_monitoring_sebaran_operasional`;
CREATE SQL SECURITY DEFINER VIEW `v_monitoring_sebaran_operasional` AS select `p`.`id` AS `id_penempatan`,`k`.`nip` AS `nip`,`k`.`nama` AS `nama`,`jl`.`nama_layanan` AS `nama_layanan`,`kl`.`nama_perusahaan` AS `nama_perusahaan`,`p`.`lokasi_kerja` AS `lokasi_kerja`,`p`.`jam_datang` AS `jam_datang`,`p`.`jam_pulang` AS `jam_pulang`,`p`.`tgl_mulai` AS `tgl_mulai`,`p`.`tgl_selesai` AS `tgl_selesai`,ifnull((to_days(`p`.`tgl_selesai`) - to_days(curdate())),9999) AS `sisa_hari_kontrak`,`p`.`id_klien` AS `id_klien`,`k`.`id_jenis_layanan` AS `id_jenis_layanan` from (((`tbl_penempatan` `p` join `tbl_karyawan` `k` on((`p`.`id_karyawan` = `k`.`id`))) left join `tbl_jenis_layanan` `jl` on((`k`.`id_jenis_layanan` = `jl`.`id`))) join `tbl_klien` `kl` on((`p`.`id_klien` = `kl`.`id`))) where (`p`.`status` = 'Aktif');

DROP VIEW IF EXISTS `v_penugasan_aktif`;
CREATE SQL SECURITY DEFINER VIEW `v_penugasan_aktif` AS select `p`.`id` AS `id_penempatan`,`p`.`id_karyawan` AS `id_karyawan`,`kl`.`nama_perusahaan` AS `nama_klien`,`p`.`lokasi_kerja` AS `lokasi_kerja`,`p`.`tgl_mulai` AS `tgl_mulai`,`p`.`tgl_selesai` AS `tgl_selesai`,`jl`.`nama_layanan` AS `nama_layanan`,`fn_jadwal_absensi`(`p`.`id`,curdate(),'datang') AS `jadwal_datang`,`fn_jadwal_absensi`(`p`.`id`,curdate(),'pulang') AS `jadwal_pulang`,`fn_sumber_jadwal_absensi`(`p`.`id`,curdate()) AS `sumber_jadwal` from (((`tbl_penempatan` `p` join `tbl_klien` `kl` on((`kl`.`id` = `p`.`id_klien`))) join `tbl_karyawan` `k` on((`k`.`id` = `p`.`id_karyawan`))) left join `tbl_jenis_layanan` `jl` on((`jl`.`id` = `k`.`id_jenis_layanan`))) where ((`p`.`status` = 'Aktif') and (`p`.`tgl_mulai` <= curdate()) and ((`p`.`tgl_selesai` is null) or (`p`.`tgl_selesai` >= curdate())));

DROP VIEW IF EXISTS `v_pertukaran_shift_snapshot`;
CREATE SQL SECURITY DEFINER VIEW `v_pertukaran_shift_snapshot` AS select `ps`.`id` AS `id`,`ps`.`tanggal_kerja` AS `tanggal_kerja`,`ps`.`tanggal_kerja_rekan` AS `tanggal_kerja_rekan`,`ps`.`status` AS `status`,`ps`.`status_rekan` AS `status_rekan`,`ps`.`id_karyawan_pengaju` AS `id_karyawan_pengaju`,`kp`.`nama` AS `nama_pengaju`,`ps`.`id_karyawan_rekan` AS `id_karyawan_rekan`,`kr`.`nama` AS `nama_rekan`,json_unquote(json_extract(`ps`.`snapshot_pengaju`,'$.status')) AS `status_jadwal_pengaju`,json_unquote(json_extract(`ps`.`snapshot_pengaju`,'$.jam_masuk')) AS `jam_masuk_pengaju`,json_unquote(json_extract(`ps`.`snapshot_pengaju`,'$.jam_pulang')) AS `jam_pulang_pengaju`,nullif(json_unquote(json_extract(`ps`.`snapshot_pengaju`,'$.nama_shift_snapshot')),'null') AS `shift_pengaju`,json_unquote(json_extract(`ps`.`snapshot_rekan`,'$.status')) AS `status_jadwal_rekan`,json_unquote(json_extract(`ps`.`snapshot_rekan`,'$.jam_masuk')) AS `jam_masuk_rekan`,json_unquote(json_extract(`ps`.`snapshot_rekan`,'$.jam_pulang')) AS `jam_pulang_rekan`,nullif(json_unquote(json_extract(`ps`.`snapshot_rekan`,'$.nama_shift_snapshot')),'null') AS `shift_rekan`,`ps`.`created_at` AS `created_at` from ((`tbl_pertukaran_shift` `ps` join `tbl_karyawan` `kp` on((`kp`.`id` = `ps`.`id_karyawan_pengaju`))) join `tbl_karyawan` `kr` on((`kr`.`id` = `ps`.`id_karyawan_rekan`)));

DROP VIEW IF EXISTS `v_pool_karyawan_hrd`;
CREATE SQL SECURITY DEFINER VIEW `v_pool_karyawan_hrd` AS select `k`.`id` AS `id`,`k`.`nip` AS `nip`,`k`.`nama` AS `nama`,`jl`.`nama_layanan` AS `nama_layanan`,`k`.`status` AS `status`,`k`.`tgl_masuk` AS `tgl_masuk` from (`tbl_karyawan` `k` join `tbl_jenis_layanan` `jl` on((`k`.`id_jenis_layanan` = `jl`.`id`))) where ((`k`.`kategori` = 'Lapangan') and (`k`.`status` = 'Tersedia'));

DROP VIEW IF EXISTS `v_rekap_absensi_pribadi`;
CREATE SQL SECURITY DEFINER VIEW `v_rekap_absensi_pribadi` AS select `k`.`id` AS `id_karyawan`,`k`.`nama` AS `nama`,month(`a`.`tgl`) AS `bulan`,year(`a`.`tgl`) AS `tahun`,count(0) AS `total_baris`,sum((`a`.`status_kehadiran` = 'Hadir')) AS `hari_hadir`,sum((`a`.`status_kehadiran` = 'Terlambat')) AS `hari_terlambat`,sum((`a`.`status_kehadiran` in ('Izin','Sakit','Alpha'))) AS `hari_tidak_hadir`,sum(`a`.`menit_terlambat`) AS `total_menit_terlambat`,sum(`a`.`jam_lembur`) AS `total_jam_lembur` from (`tbl_absensi` `a` join `tbl_karyawan` `k` on((`a`.`id_karyawan` = `k`.`id`))) group by `k`.`id`,`k`.`nama`,month(`a`.`tgl`),year(`a`.`tgl`);

DROP VIEW IF EXISTS `v_riwayat_jadwal_kerja`;
CREATE SQL SECURITY DEFINER VIEW `v_riwayat_jadwal_kerja` AS select `r`.`id` AS `id`,`r`.`id_jadwal_kerja` AS `id_jadwal_kerja`,`j`.`id_penempatan` AS `id_penempatan`,`p`.`id_karyawan` AS `id_karyawan`,`k`.`nip` AS `nip`,`k`.`nama` AS `nama`,`kl`.`nama_perusahaan` AS `nama_klien`,`j`.`tanggal_kerja` AS `tanggal_kerja`,`r`.`aksi` AS `aksi`,nullif(json_unquote(json_extract(`r`.`data_sebelum`,'$.status')),'null') AS `status_sebelum`,nullif(json_unquote(json_extract(`r`.`data_sebelum`,'$.jam_masuk')),'null') AS `jam_masuk_sebelum`,nullif(json_unquote(json_extract(`r`.`data_sebelum`,'$.jam_pulang')),'null') AS `jam_pulang_sebelum`,nullif(json_unquote(json_extract(`r`.`data_sebelum`,'$.nama_shift_snapshot')),'null') AS `shift_sebelum`,`r`.`status_sesudah` AS `status_sesudah`,nullif(json_unquote(json_extract(`r`.`data_sesudah`,'$.jam_masuk')),'null') AS `jam_masuk_sesudah`,nullif(json_unquote(json_extract(`r`.`data_sesudah`,'$.jam_pulang')),'null') AS `jam_pulang_sesudah`,nullif(json_unquote(json_extract(`r`.`data_sesudah`,'$.nama_shift_snapshot')),'null') AS `shift_sesudah`,`r`.`diubah_oleh` AS `diubah_oleh`,`u`.`nama` AS `nama_pengubah`,`r`.`created_at` AS `created_at` from (((((`tbl_jadwal_kerja_riwayat` `r` join `tbl_jadwal_kerja` `j` on((`j`.`id` = `r`.`id_jadwal_kerja`))) join `tbl_penempatan` `p` on((`p`.`id` = `j`.`id_penempatan`))) join `tbl_karyawan` `k` on((`k`.`id` = `p`.`id_karyawan`))) join `tbl_klien` `kl` on((`kl`.`id` = `p`.`id_klien`))) left join `tbl_users` `u` on((`u`.`id` = `r`.`diubah_oleh`)));

DROP VIEW IF EXISTS `v_slip_gaji_detail`;
CREATE SQL SECURITY DEFINER VIEW `v_slip_gaji_detail` AS select `p`.`id` AS `id`,`k`.`nip` AS `nip`,`k`.`nama` AS `nama`,`k`.`kategori` AS `kategori`,`p`.`periode_bulan` AS `periode_bulan`,`p`.`periode_tahun` AS `periode_tahun`,`p`.`gaji_pokok` AS `gaji_pokok`,`p`.`total_lembur` AS `total_lembur`,`p`.`potongan_absen` AS `potongan_absen`,`p`.`komponen_tunjangan` AS `komponen_tunjangan`,`p`.`potongan_pinjaman` AS `potongan_pinjaman`,`p`.`total_gaji` AS `total_gaji`,`p`.`status_bayar` AS `status_bayar`,`p`.`tgl_bayar` AS `tgl_bayar`,`p`.`hari_wajib` AS `hari_wajib`,`p`.`hari_masuk` AS `hari_masuk`,`p`.`hari_absen` AS `hari_absen`,`p`.`potongan_bpjs` AS `potongan_bpjs`,`p`.`bpjs_metode` AS `bpjs_metode`,`p`.`bpjs_nilai` AS `bpjs_nilai`,`p`.`id_klien_bpjs` AS `id_klien_bpjs`,`kl`.`nama_perusahaan` AS `nama_klien_bpjs`,`p`.`upah_backup` AS `upah_backup`,`p`.`pph21` AS `pph21`,`jl`.`nama_layanan` AS `jenis_pekerjaan`,if(((`k`.`status_pernikahan` = 'Menikah') and (`k`.`jenis_kelamin` = 'L')),'K/0','TK/0') AS `status_ptkp` from (((`tbl_payroll` `p` join `tbl_karyawan` `k` on((`p`.`id_karyawan` = `k`.`id`))) left join `tbl_jenis_layanan` `jl` on((`jl`.`id` = `k`.`id_jenis_layanan`))) left join `tbl_klien` `kl` on((`kl`.`id` = `p`.`id_klien_bpjs`)));

